import logging


from ute_common_abstract_core.device_characteristics import DeviceCharacteristics
from .exceptions import UeCharacteristicsIsEmpty


class UeCharacteristics(DeviceCharacteristics):
    """Object for encapsulating all parameters needed for ue creation."""

    def __init__(self, domain_capabilities=None, starting_cell=None, ue_capabilities=None):
        """
        :param domain_capabilities: LTE capabilities requirement
        :param ue_capabilities: instance of UeCapabilities class
        :param starting_cell: requirement for starting point of requested UE (cell identifier)
        :param abilities: (FUTURE) not domain requirement for requested UE (ability to reestablish / placeholder for the future)
        :param possible_cells: (FUTURE)  list of cell (by identifiers), that have to be reachable by UE. (RF paths)
        :raises: :py:class:`ute_ue.exceptions.UeCharacteristicsIsEmpty`: If all params are empty
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeCharacteristicsIsEmpty`: If all params are None
        """
        self.logger = logging.getLogger('ute_ue')
        # TODO check that at least one param is given
        self.starting_cell = starting_cell
        self.ue_capabilities = ue_capabilities
        super().__init__(domain_capabilities)
        # self._ensure_domain_capabilities_and_logical_tag_are_not_given_both()
        # TODO: future  '   * possible_cells:  {},\n'
        self.logger.debug('required UeCharacteristics:\n'
                          f'   * starting cell: {starting_cell},\n'
                          f'   * capabilities:  {domain_capabilities},\n')

    def _ensure_not_empty(self):
        if self._is_empty():
            raise UeCharacteristicsIsEmpty(self)

    def _is_empty(self):
        no_domain_capabilities = super()._is_empty()
        no_ue_capabilities = self.ue_capabilities is None
        no_starting_cell = self.starting_cell is None
        return no_domain_capabilities and no_ue_capabilities and no_starting_cell

    def __str__(self):
        if self._is_empty():
            return f"{self.__class__.__name__}(domain_capabilities={None}, ue_capabilities={None}, starting_cell={None})"
        domain_capabilities = self.domain_capabilities
        starting_cell = self.starting_cell

        if self.ue_capabilities:
            return f"{self.__class__.__name__}({domain_capabilities=}, {self.ue_capabilities}, {starting_cell=})"
        else:
            return f"{self.__class__.__name__}({domain_capabilities=}, {starting_cell=})"

    def __repr__(self):
        return self.__str__()
